package user

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/listfilter"
	"github.com/garamsh/garam/internal/pgxerr"
	"github.com/garamsh/garam/internal/user/db"
)

// PostgresStore implements Store against PostgreSQL. The queries are
// generated by sqlc from queries.sql.
type PostgresStore struct {
	q *db.Queries
}

// Compile-time check that PostgresStore satisfies Store.
var _ Store = (*PostgresStore)(nil)

// NewPostgresStore constructs a Postgres-backed Store.
func NewPostgresStore(pool *pgxpool.Pool) *PostgresStore {
	return &PostgresStore{q: db.New(pool)}
}

// Create persists a new User.
func (s *PostgresStore) Create(ctx context.Context, u *User) error {
	err := s.q.CreateUser(ctx, db.CreateUserParams{
		Grn:       u.grn.String(),
		Nickname:  u.nickname,
		Roles:     strs(u.roles),
		Policies:  strs(u.policies),
		CreatedAt: stamp(u.createdAt),
		UpdatedAt: stamp(u.updatedAt),
	})
	return pgxerr.Classify(err, "create", nil, nil)
}

// Get returns the User with the given GRN, or ErrUserNotFound.
func (s *PostgresStore) Get(ctx context.Context, g grn.GRN) (*User, error) {
	row, err := s.q.GetUser(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get", ErrUserNotFound, nil)
	}
	return rowToUser(row)
}

// List returns Users ordered by GRN.
func (s *PostgresStore) List(ctx context.Context, f listfilter.Filter) ([]*User, error) {
	rows, err := s.q.ListUsers(ctx, db.ListUsersParams{
		RowOffset: int32(f.Offset),
		RowLimit:  limit(f.Limit),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "list", nil, nil)
	}
	users := make([]*User, 0, len(rows))
	for _, row := range rows {
		u, err := rowToUser(row)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}

// ListByGRNs returns the Users with the given GRNs, ordered by GRN.
// GRNs without a user are absent from the result.
func (s *PostgresStore) ListByGRNs(ctx context.Context, grns []grn.GRN) ([]*User, error) {
	if len(grns) == 0 {
		return []*User{}, nil
	}
	keys := make([]string, 0, len(grns))
	for _, g := range grns {
		keys = append(keys, g.String())
	}
	rows, err := s.q.ListUsersByGRNs(ctx, keys)
	if err != nil {
		return nil, pgxerr.Classify(err, "list by grns", nil, nil)
	}
	users := make([]*User, 0, len(rows))
	for _, row := range rows {
		u, err := rowToUser(row)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	return users, nil
}

// Update applies a Patch and returns the updated User.
func (s *PostgresStore) Update(ctx context.Context, g grn.GRN, p Patch) (*User, error) {
	row, err := s.q.UpdateUser(ctx, db.UpdateUserParams{
		Grn:       g.String(),
		Nickname:  text(p.Nickname),
		Roles:     p.Roles,
		Policies:  p.Policies,
		UpdatedAt: stamp(time.Now().UTC()),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "update", ErrUserNotFound, nil)
	}
	return rowToUser(row)
}

// Delete removes the User with the given GRN.
func (s *PostgresStore) Delete(ctx context.Context, g grn.GRN) error {
	n, err := s.q.DeleteUser(ctx, g.String())
	if err != nil {
		return pgxerr.Classify(err, "delete", nil, nil)
	}
	if n == 0 {
		return ErrUserNotFound
	}
	return nil
}

// rowToUser converts a sqlc row into the domain aggregate. A stored
// value that no longer parses is data corruption, hence internal.
func rowToUser(row db.User) (*User, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "user row grn", errorx.KindInternal)
	}
	return &User{
		grn:       g,
		nickname:  row.Nickname,
		roles:     row.Roles,
		policies:  row.Policies,
		createdAt: row.CreatedAt.Time,
		updatedAt: row.UpdatedAt.Time,
	}, nil
}

// strs normalizes a nil slice to empty: pgx encodes a nil slice as// NULL, which the NOT NULL array columns reject.
func strs(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}

// text converts a *string patch field to a nullable text.
func text(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

// limit converts a list filter's limit: 0 means "no limit" (SQL NULL).
func limit(n int) pgtype.Int4 {
	if n <= 0 {
		return pgtype.Int4{}
	}
	return pgtype.Int4{Int32: int32(n), Valid: true}
}
